effect.shader:
void main() {
vec2 uv = acScreenNorm;
float rad = radians(angle);
vec2 dirR = vec2(cos(rad), sin(rad)) * distance;
vec2 dirB = vec2(cos(rad + 3.1415), sin(rad + 3.1415)) * distance;
float r = texture2DCv(inputImg.texture, uv + dirR).r;
float g = texture2DCv(inputImg.texture, uv).g;
float b = texture2DCv(inputImg.texture, uv + dirB).b;
gl_FragColor = vec4(r, g, b, texture2DCv(inputImg.texture, uv).a);
}
